  -- reading: a1-one-page-at-a-time (A1)
  if exists (select 1 from public.reading_articles where product_id = v_product_reading and language_id = v_en_id and slug = 'a1-one-page-at-a-time') then
    raise notice 'skipped existing reading item %', 'a1-one-page-at-a-time';
  else
    insert into public.reading_articles (slug, title, level, status, sort_order, metadata, summary, content_markdown, category, theme, tone, read_time_minutes, is_hot, questions, product_id, language_id)
