    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"a1-watch-the-aquarium-feeding","title":"Watch the aquarium feeding","level":"A1","status":"published","sort_order":200,"metadata":{"format":"monologue","script_type":"monologue","speakers":[]},"summary":"An aquarium announcement tells visitors when and where to watch the fish.","transcript_text":"Good morning. The fish feeding starts at eleven in the small room, next to the café. Please stand behind the yellow line. You can take photos, but please turn off the flash. There is another feeding at two. The café stays open until four.","category":"Leisure","accent":"general","speed_label":"slow","speed_wpm":100,"duration_seconds":27,"audio_url":null,"focus_skill":"detail","tags":["leisure","monologue"],"questions":[{"id":"q1","type":"mcq","prompt":"What is the message mainly about?","options":["Changes to the café menu","How to watch the fish feeding","Buying tickets for the shop","How to look after a fish at home"],"answer_index":1,"explanation":"The speaker tells visitors about the feeding times, location and rules."},{"id":"q2","type":"mcq","prompt":"Where is the fish feeding?","options":["In the café","In the shop","In the small room next to the café","Outside the aquarium"],"answer_index":2,"explanation":"The small room beside the café is the location. The café is a landmark."},{"id":"q3","type":"mcq","prompt":"When is the second feeding?","options":["At two","At eleven","At four","At twelve"],"answer_index":0,"explanation":"Eleven is the first feeding and four is the café closing time. The second feeding is at two."},{"id":"q4","type":"mcq","prompt":"What should people do with their cameras?","options":["Put them in a bag","Only take pictures outside","Use them with the flash on","Turn the flash off"],"answer_index":3,"explanation":"Photos are allowed as long as visitors turn off the flash."}]}$seed$::jsonb) r
