    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"a2-rent-skates-for-two","title":"Rent skates for two","level":"A2","status":"published","sort_order":200,"metadata":{"format":"dialogue","script_type":"dialogue","speakers":["Aida","Clerk"]},"summary":"Two visitors work out rental sizes and return times at an ice rink.","transcript_text":"Aida: We need skates for the four o'clock session. I wear size thirty-eight, and my brother wears forty.\nClerk: We have thirty-eight, but the size forty pairs are still out. One should come back at ten to four.\nAida: Can we both go on the ice at four?\nClerk: Yes. I'll keep the next pair for your brother. Please collect both pairs together. Return them by quarter past five. You can leave your shoes on the shelf, but lockers need a coin.\nAida: We'll wait and collect the two pairs together.","category":"Leisure","accent":"general","speed_label":"slow","speed_wpm":112,"duration_seconds":47,"audio_url":null,"focus_skill":"detail","tags":["leisure","dialogue"],"questions":[{"id":"q1","type":"mcq","prompt":"What are Aida and the clerk arranging?","options":["Skate hire for two people before a session","A lesson for a first-time skater","An exchange for skates bought online","A booking for a private birthday group"],"answer_index":0,"explanation":"The clerk works out how Aida and her brother can collect both sizes and return them after the session."},{"id":"q2","type":"mcq","prompt":"Which pair must they wait for?","options":["Size thirty-eight","Size forty","Both sizes","The size they already have at home"],"answer_index":1,"explanation":"The clerk has size thirty-eight available now, while the size forty pairs are still out."},{"id":"q3","type":"mcq","prompt":"When must they return the skates?","options":["At four","Before ten to four","By quarter past five","At half past five"],"answer_index":2,"explanation":"The clerk specifically asks for both pairs back by 5:15."},{"id":"q4","type":"mcq","prompt":"When do they need a coin?","options":["To reserve the four o'clock session","To leave shoes on a shelf","To rent two pairs at once","To use a locker"],"answer_index":3,"explanation":"The shelf is available for shoes. The coin is for a locker."}]}$seed$::jsonb) r
