  if exists (select 1 from public.grammar_units where product_id = v_product_grammar and language_id = v_en_id and slug = 'b1-past-continuous-in-a-power-cut') then
    raise notice 'skipped existing grammar item %', 'b1-past-continuous-in-a-power-cut';
  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"b1-past-continuous-in-a-power-cut","title":"Past continuous and past simple during a power cut","level":"B1","status":"published","sort_order":340,"metadata":{},"focus_area":"past-continuous-and-past-simple","explanation_text":"Use was or were + verb-ing to show an action already in progress at a past time. At eight o’clock, the volunteers were packing food boxes. The packing is the activity we can picture at that moment. The sentence does not tell us exactly when they started or finished.\n\nUse the past simple for a completed event in the story. “The lights went out” describes a change. These patterns often appear together: “We were packing boxes when the lights went out.” The longer action provides the background, and the shorter event happens during it. It does not have to stop the longer action. “I was carrying a box when Maya waved” does not say that I put the box down.\n\nYou can put the background first with while: “While the caretaker was checking the hallway, a phone rang.” Look at the timeline first. Words such as when and while can help you see the relationship, but the meaning tells you which tense to choose.","contrast_text":"“At nine, I opened the hall” places the opening at nine. “At nine, I was opening the hall” shows me in the process of opening it around nine.","common_error_pattern":"Keep was or were before the -ing form. In a story, check which event is already in progress and which happens during it.","examples_json":[{"bad":"We were pack the boxes when the lights failed.","good":"We were packing the boxes when the lights failed."},{"bad":"At eight, I were waiting by the door.","good":"At eight, I was waiting by the door."},{"bad":"She was carrying the tray when the bell ringed.","good":"She was carrying the tray when the bell rang."},{"bad":"While the volunteers stacking chairs, the caretaker opened the side door.","good":"While the volunteers were stacking chairs, the caretaker opened the side door."}],"tags":["past continuous","past simple","background"]}$seed$::jsonb) r
