  -- grammar: b2-future-continuous-and-perfect-in-a-build (B2)
  if exists (select 1 from public.grammar_units where product_id = v_product_grammar and language_id = v_en_id and slug = 'b2-future-continuous-and-perfect-in-a-build') then
    raise notice 'skipped existing grammar item %', 'b2-future-continuous-and-perfect-in-a-build';
  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"b2-future-continuous-and-perfect-in-a-build","title":"Future continuous and future perfect in a build schedule","level":"B2","status":"published","sort_order":340,"metadata":{},"focus_area":"future-continuous-and-future-perfect","explanation_text":"A build schedule can describe work in progress at a future time or work already complete at that time. Use will be + verb-ing for an activity in progress. “At ten on Friday, we will be testing the display” puts the reader inside the testing period. It leaves the exact finishing time open.\n\nUse will have + past participle to look back from a deadline. “By noon on Friday, we will have completed the tests” says we expect completion by noon. It allows an earlier finish. With an irregular verb, use the past participle: “We will have sent the files”, with sent after have.\n\nThe same schedule can use both forms: testing may be in progress at ten, and the testing may be complete by noon. A future time phrase alone does not choose the form. Decide whether the sentence describes being in the middle of the job or having it behind you at the stated time.","contrast_text":"“At noon, the team will be fitting the panels” puts the fitting in progress at noon. “By noon, the team will have fitted the panels” puts the completion at or before noon.","common_error_pattern":"After will have, use the past participle. After will be in the future continuous, use the -ing form.","examples_json":[{"bad":"By Tuesday, we will have send the fixture list.","good":"By Tuesday, we will have sent the fixture list."},{"bad":"At eleven, the installers will be fit the panels.","good":"At eleven, the installers will be fitting the panels."},{"bad":"By July, I will have wrote the maintenance guide.","good":"By July, I will have written the maintenance guide."},{"bad":"At four, the technician will checking the sensors.","good":"At four, the technician will be checking the sensors."}],"tags":["future continuous","future perfect","deadlines"]}$seed$::jsonb) r
