  -- grammar: c1-nominalization-in-an-inspection-report (C1)
  if exists (select 1 from public.grammar_units where product_id = v_product_grammar and language_id = v_en_id and slug = 'c1-nominalization-in-an-inspection-report') then
    raise notice 'skipped existing grammar item %', 'c1-nominalization-in-an-inspection-report';
  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"c1-nominalization-in-an-inspection-report","title":"Nominalization and agency in an inspection report","level":"C1","status":"published","sort_order":340,"metadata":{},"focus_area":"nominalization-and-agency","explanation_text":"A nominalization turns an action or process into a noun. “The crew inspected the bearings” can become “the crew’s inspection of the bearings”. The noun phrase lets a report refer to the whole event as the subject of a new sentence: “The crew’s inspection of the bearings revealed three faults.”\n\nCheck what the noun needs. Inspection can take an of phrase for the thing inspected. Decision can take a to-infinitive for the action agreed on: “the decision to close the lane”. Different nouns take different complements, so carry the meaning across and check the pattern.\n\nKeep the roles visible if they matter. In “the inspection of the pump by the contractor”, the pump was inspected and the contractor did the work. A possessive can also identify the doer when the meaning is clear. Choosing a noun can help a report connect ideas, but several vague noun phrases can bury the action and the responsible person. Read the finished sentence and check whether each role is still apparent.","contrast_text":"“The coordinator approved the schedule” directly states the action. “The coordinator’s approval of the schedule” names it and can serve as the subject of another statement, such as “The coordinator’s approval of the schedule came today.”","common_error_pattern":"A nominalization can hide the doer. Keep the person or team in a possessive or a by-phrase when accountability matters, and use the complement that fits the action noun.","examples_json":[{"bad":"The team’s inspection the lift took two hours.","good":"The team’s inspection of the lift took two hours."},{"bad":"The committee’s decision to closing the lane was announced at noon.","good":"The committee’s decision to close the lane was announced at noon."},{"bad":"The contractor’s removal of the old signs require an extra visit yesterday.","good":"The contractor’s removal of the old signs required an extra visit yesterday."},{"bad":"The engineers’ evaluation the drainage plan took a week.","good":"The engineers’ evaluation of the drainage plan took a week."}],"tags":["nominalization","noun phrases","agency"]}$seed$::jsonb) r
    returning id into v_parent_id;
