  -- grammar: c2-as-if-and-modal-distance (C2)
  if exists (select 1 from public.grammar_units where product_id = v_product_grammar and language_id = v_en_id and slug = 'c2-as-if-and-modal-distance') then
    raise notice 'skipped existing grammar item %', 'c2-as-if-and-modal-distance';
  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"c2-as-if-and-modal-distance","title":"As if, as though and distance from reality","level":"C2","status":"published","sort_order":340,"metadata":{},"focus_area":"as-if-modal-remoteness","explanation_text":"After as if or as though, a speaker can describe an impression without confirming it. “It looks as though the door is locked” uses the ordinary present because a locked door is a real possibility. The form reports the impression and leaves room for doubt.\n\nA past form can put some distance between a present appearance and what the speaker takes to be real. “He talks as if he owned the hall” can imply he does not own it. In formal English, were can mark this distance with a singular subject: “She acts as though she were in charge.” Was is also heard in ordinary conversation. An actual past narrative can contain past forms too, so tense alone does not prove that the comparison is unreal.\n\nWhen the imagined situation is earlier than the behavior we are describing, the past perfect can mark that earlier time: “She greets us as if she had never seen us before.” Context can make the imaginary comparison clear, for example by stating that we met yesterday.","contrast_text":"“It sounds as if the caretaker knows the code” entertains a real possibility. “He speaks as if he knew every code, though I know he has only one” imagines a wider knowledge that conflicts with what the speaker knows.","common_error_pattern":"Look for evidence of the speaker’s stance and of the comparison’s time. A past form after as if can mark distance from a present reality or simply belong to a past context.","examples_json":[{"bad":"She is not the director, but she acts as if were she in charge.","good":"She is not the director, but she acts as if she were in charge."},{"bad":"It looks as though is the room empty.","good":"It looks as though the room is empty."},{"bad":"They had met before, but he greeted her as if he had never saw her.","good":"They had met before, but he greeted her as if he had never seen her."},{"bad":"It's possible the bell is broken. It sounds as like the bell is broken.","good":"It's possible the bell is broken. It sounds as if the bell is broken."}],"tags":["as if","as though","modal remoteness"]}$seed$::jsonb) r
    returning id into v_parent_id;
